-- Pollution (PPCB): seven combined questions split (PL02/PL12, PL03/PL13, PL05/PL14-16, PL06/PL17, PL07/PL18, PL08/PL19, PL09/PL20, PL10/PL21).
update public.hub_chk_points set q='Is Consent to Operate (Air and Water) valid?', why='Running without valid consent can shut the unit and cut power.', law='Water Act s.25–26; Air Act s.21', evidence='CTO', updated_at=now() where code='PL02';
update public.hub_chk_points set q='Is the effluent treatment plant running daily, with a logbook?', why='A switched-off ETP is the most common reason for PPCB closure orders.', law='Water Act; E(P) Rules', evidence='ETP logbook', updated_at=now() where code='PL03';
update public.hub_chk_points set q='Is the hazardous waste authorisation valid?', why='Illegal disposal brings personal liability on the owner.', law='Hazardous Waste Rules 2016', evidence='Authorisation', updated_at=now() where code='PL05';
update public.hub_chk_points set q='Is bio-medical waste from the lab handed to the authorised collector, with an agreement?', why='Applies to microbiology labs and first-aid rooms.', law='Bio-Medical Waste Rules 2016', evidence='Agreement', updated_at=now() where code='PL06';
update public.hub_chk_points set q='Is the firm registered on the CPCB plastic EPR portal?', why='Unregistered brand owners cannot legally sell in plastic packaging.', law='Plastic Waste Management Rules 2016 (EPR)', evidence='EPR registration', updated_at=now() where code='PL07';
update public.hub_chk_points set q='Is there permission for the borewell?', why='Unpermitted borewells can be sealed.', law='Punjab groundwater directions (PWRDA)', evidence='Permission', updated_at=now() where code='PL08';
update public.hub_chk_points set q='Does the DG set have an acoustic enclosure?', why='Standard consent condition.', law='E(P) Rules, DG set norms', evidence='DG photo + spec', updated_at=now() where code='PL09';
update public.hub_chk_points set q='Was the yearly environment statement (Form V) filed?', why='Late filing delays consent renewal.', law='E(P) Rules r.14', evidence='Form V acknowledgement', updated_at=now() where code='PL10';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL12','Pollution (PPCB)','Is production within the products and quantity allowed in the consent?','Producing beyond the consent is treated as running without consent.','Water Act s.25–26; Air Act s.21','ppcb',array['ppcb']::text[],'H','Production vs consent sheet',9962,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL13','Pollution (PPCB)','Are lab test reports of the treated water kept?','Consent renewal and inspections ask for treated-water test reports.','Water Act; E(P) Rules','ppcb',array['ppcb']::text[],'H','Lab test reports',9963,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL14','Pollution (PPCB)','Is hazardous waste stored for under 90 days?','Illegal disposal brings personal liability on the owner.','Hazardous Waste Rules 2016','haz_waste',array['ppcb']::text[],'H','Storage record',9964,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL15','Pollution (PPCB)','Is hazardous waste recorded (Form 3)?','Illegal disposal brings personal liability on the owner.','Hazardous Waste Rules 2016','haz_waste',array['ppcb']::text[],'H','Form 3 register',9965,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL16','Pollution (PPCB)','Is hazardous waste sent only to an authorised facility, with manifests?','Illegal disposal brings personal liability on the owner.','Hazardous Waste Rules 2016','haz_waste',array['ppcb']::text[],'H','Manifests',9966,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL17','Pollution (PPCB)','Are bio-medical waste collection records kept?','Applies to microbiology labs and first-aid rooms.','Bio-Medical Waste Rules 2016','bmw',array['ppcb']::text[],'M','Collection slips',9967,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL18','Pollution (PPCB)','Are the yearly plastic recycling targets met?','Unmet EPR targets bring environmental compensation.','Plastic Waste Management Rules 2016 (EPR)','pibo',array['ppcb']::text[],'H','EPR certificates',9968,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL19','Pollution (PPCB)','Is a water meter fitted on the borewell?','Unpermitted borewells can be sealed.','Punjab groundwater directions (PWRDA)','groundwater',array['ppcb']::text[],'M','Meter readings',9969,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL20','Pollution (PPCB)','Is the DG set stack at the correct height?','Standard consent condition.','E(P) Rules, DG set norms','mfg',array['ppcb']::text[],'L','Stack measurement',9970,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('PL21','Pollution (PPCB)','Are consent fees paid?','Unpaid fees delay consent renewal.','E(P) Rules r.14','ppcb',array['ppcb']::text[],'M','Fee receipts',9971,true,null) on conflict (code) do nothing;
